import { mulberry32, shuffled } from './rng';

const NEUTRAL = '#f4f0df';
const ACCENTS = ['#d7261e', '#1357a6', '#f3c623'] as const;

export type GridComposition = {
  rows: number[];
  columns: number[];
  cells: Array<{ id: string; color: string }>;
};

function trackWeights(count: number, random: () => number): number[] {
  return Array.from({ length: count }, () => Number((0.7 + random() * 1.8).toFixed(3)));
}

export function createGridComposition(seed: number): GridComposition {
  const random = mulberry32(seed);
  const rows = trackWeights(4 + Math.floor(random() * 2), random);
  const columns = trackWeights(5 + Math.floor(random() * 2), random);
  const cells = Array.from({ length: rows.length * columns.length }, (_, index) => ({
    id: `cell-${index}`,
    color: NEUTRAL,
  }));
  const accentIndexes = shuffled(cells.map((_, index) => index), random).slice(0, ACCENTS.length);
  accentIndexes.forEach((cellIndex, index) => {
    cells[cellIndex].color = ACCENTS[index];
  });
  return { rows, columns, cells };
}

