import { mulberry32, shuffled } from './rng';

type Cell = { id: string; x: number; y: number; width: number; height: number; color: string };
export type SvgComposition = { xCuts: number[]; yCuts: number[]; cells: Cell[] };
const NEUTRAL = '#f4f0df';
const ACCENTS = ['#d7261e', '#1357a6', '#f3c623'] as const;

function cuts(total: number, segments: number, random: () => number): number[] {
  const weights = Array.from({ length: segments }, () => 0.75 + random() * 1.7);
  const sum = weights.reduce((value, weight) => value + weight, 0);
  const result = [0];
  weights.forEach((weight) => result.push(result[result.length - 1] + (weight / sum) * total));
  result[result.length - 1] = total;
  return result.map((value) => Number(value.toFixed(3)));
}

export function createSvgComposition(seed: number): SvgComposition {
  const random = mulberry32(seed);
  const xCuts = cuts(100, 5 + Math.floor(random() * 2), random);
  const yCuts = cuts(75, 4 + Math.floor(random() * 2), random);
  const cells: Cell[] = [];
  for (let row = 0; row < yCuts.length - 1; row += 1) {
    for (let column = 0; column < xCuts.length - 1; column += 1) {
      cells.push({ id: `${row}-${column}`, x: xCuts[column], y: yCuts[row], width: xCuts[column + 1] - xCuts[column], height: yCuts[row + 1] - yCuts[row], color: NEUTRAL });
    }
  }
  shuffled(cells.map((_, index) => index), random).slice(0, ACCENTS.length).forEach((cellIndex, accentIndex) => {
    cells[cellIndex].color = ACCENTS[accentIndex];
  });
  return { xCuts, yCuts, cells };
}

