export type LogEvent = Readonly<{ id: bigint; key: string; value: unknown }>;
export type Options = { blockSize?: number; autoThreshold?: number; cooldown?: number; maxNodes?: number };
export type Cursor = { next(limit?: number): LogEvent[]; readonly nextOffset: bigint };
type SimulatedNode = { id: number; eventCount: number; keys: Map<string, KeyStore> };

function integer(value: number, min: number, max = Number.MAX_SAFE_INTEGER): void {
  if (!Number.isSafeInteger(value) || value < min || value > max) throw new RangeError("Invalid integer");
}
function keyCheck(key: string): void {
  if (typeof key !== "string" || key.length === 0) throw new TypeError("Use a nonempty key");
}
function offsetCheck(offset: bigint): void {
  if (typeof offset !== "bigint" || offset < 0n) throw new RangeError("Use a nonnegative bigint offset");
}
// First index for which predicate is false. No copied prefix or suffix.
function boundary(length: number, before: (index: number) => boolean): number {
  let lo = 0, hi = length;
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (before(mid)) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

// One coordinator in ONE JavaScript agent. Methods never await or call user code.
// Nodes are ownership maps in this heap, not network workers or durable brokers.
export class EventLog {
  private nextId = 0n;
  private readonly nodes: SimulatedNode[] = [{ id: 0, eventCount: 0, keys: new Map() }];
  private readonly owners = new Map<string, number>();
  private readonly global: GlobalIndex;
  private readonly blockSize: number;
  private readonly autoThreshold: number | undefined;
  private readonly cooldown: bigint;
  private readonly maxNodes: number;
  private nextGrowthAt = 0n;

  constructor(options: Options = {}) {
    this.blockSize = options.blockSize ?? 1024;
    this.autoThreshold = options.autoThreshold;
    this.maxNodes = options.maxNodes ?? 8;
    integer(this.blockSize, 1, 65536);
    integer(this.maxNodes, 1, 1024);
    integer(options.cooldown ?? 10000, 1);
    if (this.autoThreshold !== undefined) integer(this.autoThreshold, 1);
    this.cooldown = BigInt(options.cooldown ?? 10000);
    this.global = new GlobalIndex(this.blockSize);
  }

  append(key: string, value: unknown): bigint {
    keyCheck(key);
    this.global.checkCapacity();
    let owner = this.owners.get(key);
    if (owner === undefined) {
      owner = 0;
      for (const node of this.nodes) if (node.eventCount < this.nodes[owner].eventCount) owner = node.id;
      this.owners.set(key, owner);
      this.nodes[owner].keys.set(key, new KeyStore(this.blockSize));
    }
    const node = this.nodes[owner];
    const event: LogEvent = Object.freeze({ id: this.nextId, key, value });
    // Store/index publication and ID allocation form one synchronous operation.
    node.keys.get(key)!.append(event);
    this.global.append(event);
    node.eventCount++;
    this.nextId++;
    if (this.autoThreshold !== undefined && node.eventCount > this.autoThreshold &&
        this.nextId >= this.nextGrowthAt && this.nodes.length < this.maxNodes) {
      // Cool down even when one hot key cannot be split.
      this.nextGrowthAt = this.nextId + this.cooldown;
      if (this.movable()) this.addNode();
    }
    return event.id;
  }

  read(fromOffset = 0n, limit = 100): LogEvent[] {
    offsetCheck(fromOffset); integer(limit, 0, 10000);
    const result: LogEvent[] = [];
    const end = this.nextId; // Only fully published events from this call.
    for (let id = fromOffset; id < end && result.length < limit; id++) result.push(this.global.get(id));
    return result;
  }

  readKey(key: string, fromOffset = 0n, limit = 100): LogEvent[] {
    return this.cursor(key, fromOffset).next(limit);
  }

  cursor(key: string, fromOffset = 0n): Cursor {
    keyCheck(key); offsetCheck(fromOffset);
    let nextOffset = fromOffset;
    let take: (() => LogEvent | undefined) | undefined;
    return {
      get nextOffset() { return nextOffset; },
      next: (limit = 100) => {
        integer(limit, 0, 10000);
        const result: LogEvent[] = [];
        if (limit === 0) return result;
        if (!take) {
          const owner = this.owners.get(key);
          if (owner === undefined) return result;
          // The bucket object survives ownership movement between node maps.
          take = this.nodes[owner].keys.get(key)!.reader(fromOffset);
        }
        while (result.length < limit) {
          const event = take();
          if (!event) break;
          result.push(event);
          nextOffset = event.id + 1n;
        }
        return result;
      },
    };
  }

  // Choose the busiest node and a whole key no larger than half its load.
  // This is a simple heuristic, not globally optimal bin packing.
  private movable(): { node: SimulatedNode; key: string; store: KeyStore } | undefined {
    let node = this.nodes[0];
    for (const candidate of this.nodes) if (candidate.eventCount > node.eventCount) node = candidate;
    let chosen: { node: SimulatedNode; key: string; store: KeyStore } | undefined;
    for (const [key, store] of node.keys) {
      if (store.count > 0 && store.count <= node.eventCount / 2 && (!chosen || store.count > chosen.store.count)) chosen = { node, key, store };
    }
    return chosen;
  }

  addNode(): number {
    const move = this.movable();
    const node: SimulatedNode = { id: this.nodes.length, eventCount: 0, keys: new Map() };
    this.nodes.push(node); // Explicit additions are not subject to the automatic cap.
    if (move) {
      move.node.keys.delete(move.key);
      move.node.eventCount -= move.store.count;
      node.keys.set(move.key, move.store);
      node.eventCount = move.store.count;
      this.owners.set(move.key, node.id);
    }
    return node.id;
  }

  stats(): { id: number; eventCount: number; keys: string[] }[] {
    return this.nodes.map((node) => ({ id: node.id, eventCount: node.eventCount, keys: [...node.keys.keys()] }));
  }
}

// IDs are monotonic, so append preserves ordering without sorting or insort.
class KeyStore {
  private readonly events: LogEvent[] = [];
  constructor(_blockSize: number) {}
  get count(): number { return this.events.length; }
  append(event: LogEvent): void { this.events.push(event); }
  reader(offset: bigint): () => LogEvent | undefined {
    let position = boundary(this.events.length, (i) => this.events[i].id < offset);
    return () => {
      // A cursor opened beyond the current tail waits for that future ID.
      while (position < this.events.length && this.events[position].id < offset) position++;
      return position < this.events.length ? this.events[position++] : undefined;
    };
  }
}
class GlobalIndex {
  private readonly events: LogEvent[] = [];
  constructor(_blockSize: number) {}
  checkCapacity(): void {
    if (this.events.length >= 0xffffffff) throw new RangeError("Flat array capacity reached");
  }
  append(event: LogEvent): void { this.events.push(event); }
  get(id: bigint): LogEvent { return this.events[Number(id)]; }
}

