  }

  stats(): { id: number; eventCount: number; keys: string[] }[] {
    return this.nodes.map((node) => ({ id: node.id, eventCount: node.eventCount, keys: [...node.keys.keys()] }));
  }
}

class KeyStore {
  private readonly blocks: LogEvent[][] = [];
  count = 0;
  constructor(private readonly blockSize: number) {}
  append(event: LogEvent): void {
    if (this.count % this.blockSize === 0) this.blocks.push([]);
