    // If the seek is beyond the tail, retain the partly filled final block.
    if (block === this.blocks.length && block > 0) block--;
    let slot = this.blocks[block] ? boundary(this.blocks[block].length, (i) => this.blocks[block][i].id < offset) : 0;
    return () => {
      while (block < this.blocks.length) {
        const items = this.blocks[block];
        if (slot === items.length) {
          if (block + 1 === this.blocks.length) return undefined;
          block++; slot = 0; continue;
        }
        const event = items[slot++];
        if (event.id >= offset) return event;
      }
      return undefined;
    };
  }
}
