  private readonly blocks = new Map<bigint, LogEvent[]>();
  constructor(private readonly blockSize: number) {}
  checkCapacity(): void {} // Physical memory remains finite; no durability is implied.
  append(event: LogEvent): void {
    const block = event.id / BigInt(this.blockSize);
    if (!this.blocks.has(block)) this.blocks.set(block, []);
    this.blocks.get(block)!.push(event);
  }
  get(id: bigint): LogEvent {
    return this.blocks.get(id / BigInt(this.blockSize))![Number(id % BigInt(this.blockSize))];
  }
}

