from dataclasses import dataclass
from threading import RLock

@dataclass(frozen=True, slots=True)
class Event:
    id: int
    key: str
    value: object

def integer(value, minimum=0, maximum=None):
    if type(value) is not int or value < minimum or (maximum is not None and value > maximum):
        raise ValueError("Invalid integer")

def check_key(key):
    if not isinstance(key, str) or not key:
        raise ValueError("Use a nonempty key")

def boundary(length, before):
    lo, hi = 0, length
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if before(mid):
            lo = mid + 1
        else:
            hi = mid
    return lo

class Cursor:
    def __init__(self, log, key, offset):
        self._log, self._key = log, key
        self._offset = self._next_offset = offset
        self._take = None

    @property
    def next_offset(self):
        with self._log._lock:
            return self._next_offset

    def next(self, limit=100):
        integer(limit, 0, 10000)
        result = []
        # Bound the page; never yield to caller code while holding this lock.
        with self._log._lock:
            if limit == 0:
                return result
            if self._take is None:
                owner = self._log._owners.get(self._key)
                if owner is None:
                    return result
                self._take = self._log._nodes[owner]['keys'][self._key].reader(self._offset)
            while len(result) < limit:
                event = self._take()
                if event is None:
                    break
                result.append(event)
                self._next_offset = event.id + 1
        return result

class EventLog:
    def __init__(self, *, block_size=1024, auto_threshold=None, cooldown=10000, max_nodes=8):
        integer(block_size, 1, 65536)
        integer(cooldown, 1)
        integer(max_nodes, 1, 1024)
        if auto_threshold is not None:
            integer(auto_threshold, 1)
        self._lock = RLock()
        self._next_id = 0
        self._nodes = [dict(id=0, event_count=0, keys={})]
        self._owners = {}
        self._global = GlobalIndex(block_size)
        self._block_size = block_size
        self._threshold, self._cooldown, self._max_nodes = auto_threshold, cooldown, max_nodes
        self._next_growth_at = 0

    def append(self, key, value):
        check_key(key)
        with self._lock:
            self._global.check_capacity()
            if key not in self._owners:
                owner = min(range(len(self._nodes)), key=lambda i: self._nodes[i]['event_count'])
                self._owners[key] = owner
                self._nodes[owner]['keys'][key] = KeyStore(self._block_size)
            node = self._nodes[self._owners[key]]
            event = Event(self._next_id, key, value)
            node['keys'][key].append(event)
            self._global.append(event)
            node['event_count'] += 1
            self._next_id += 1
            if (self._threshold is not None and node['event_count'] > self._threshold
                    and self._next_id >= self._next_growth_at and len(self._nodes) < self._max_nodes):
                self._next_growth_at = self._next_id + self._cooldown
                if self._movable() is not None:
                    self.add_node()  # RLock allows this nested acquisition.
            return event.id

    def read(self, from_offset=0, limit=100):
        integer(from_offset)
        integer(limit, 0, 10000)
        result = []
        with self._lock:
            position = from_offset
            while position < self._next_id and len(result) < limit:
                result.append(self._global.get(position))
                position += 1
        return result

    def cursor(self, key, from_offset=0):
        check_key(key)
        integer(from_offset)
        return Cursor(self, key, from_offset)

    def read_key(self, key, from_offset=0, limit=100):
        return self.cursor(key, from_offset).next(limit)

    def _movable(self):
        node = max(self._nodes, key=lambda n: n['event_count'])
        chosen = None
        for key, store in node['keys'].items():
            if 0 < store.count <= node['event_count'] // 2 and (chosen is None or store.count > chosen[2].count):
                chosen = (node, key, store)
        return chosen

    def add_node(self):
        with self._lock:
            move = self._movable()
            node = dict(id=len(self._nodes), event_count=0, keys={})
            self._nodes.append(node)
            if move is not None:
                donor, key, store = move
                del donor['keys'][key]
                donor['event_count'] -= store.count
                node['keys'][key] = store
                node['event_count'] = store.count
                self._owners[key] = node['id']
            return node['id']

    def stats(self):
        with self._lock:
            return [dict(id=n['id'], event_count=n['event_count'], keys=list(n['keys'])) for n in self._nodes]

class KeyStore:
    def __init__(self, block_size):
        self.blocks = []
        self.count = 0
        self.block_size = block_size

    def append(self, event):
        if self.count % self.block_size == 0:
            self.blocks.append([])
        self.blocks[-1].append(event)
        self.count += 1

    def reader(self, offset):
        block = boundary(len(self.blocks), lambda i: self.blocks[i][-1].id < offset)
        if block == len(self.blocks) and block > 0:
            block -= 1
        slot = boundary(len(self.blocks[block]), lambda i: self.blocks[block][i].id < offset) if self.blocks else 0
        def take():
            nonlocal block, slot
            while block < len(self.blocks):
                items = self.blocks[block]
                if slot == len(items):
                    if block + 1 == len(self.blocks):
                        return None
                    block, slot = block + 1, 0
                    continue
                event = items[slot]
                slot += 1
                if event.id >= offset:
                    return event
            return None
        return take

class GlobalIndex:
    def __init__(self, block_size):
        self.blocks = {}
        self.block_size = block_size

    def check_capacity(self):
        pass  # Still bounded by available RAM.

    def append(self, event):
        block = event.id // self.block_size
        if block not in self.blocks:
            self.blocks[block] = []
        self.blocks[block].append(event)

    def get(self, event_id):
        block, slot = divmod(event_id, self.block_size)
        return self.blocks[block][slot]

